import{_ as t,o as n,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"title":"FAQ"},"headers":[],"relativePath":"projects/uix/faq.md","filePath":"projects/uix/faq.md","lastUpdated":1792754181000}'),i={name:"projects/uix/faq.md"};function d(s,e,l,o,c,u){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="wie-migriere-ich-am-besten-von-card-mod" tabindex="-1">Wie migriere ich am besten von Card-mod? <a class="header-anchor" href="#wie-migriere-ich-am-besten-von-card-mod" aria-label="Permalink to &quot;Wie migriere ich am besten von Card-mod?&quot;">​</a></h2><p>Deinstalliere zuerst Card-mod. Falls dessen Ressource über <code>extra_module_url</code> geladen wird, entferne auch diesen Eintrag und starte HA neu. Folge anschließend dem <a href="./quick-start">UIX-Schnellstart</a>, einschließlich des Hinzufügens der Integration als Dienst. Beide Ressourcen sollen nicht parallel geladen werden.</p><div class="warning custom-block"><p class="custom-block-title">UI Lovelace Minimalist kann Card-mod nachladen</p><p>Deaktiviere dort die Option <code>Include custom card resources it&#39;s depending on</code> und lade benötigte Custom Cards über HACS oder manuell. Durch die Ladereihenfolge kann UIX diesen Konflikt nicht selbst erkennen.</p></div><div class="tip custom-block"><p class="custom-block-title">UI eXtension als Service hinzufügen</p><p>Wenn UIX als Home-Assistant-Integration installiert ist, kümmert sich UIX selbst um die Frontend-Ressource. Dadurch entfallen typische Probleme mit manuell gepflegten Ressourcen-URLs.</p></div><h2 id="ist-ui-extension-ein-direkter-ersatz-fur-card-mod" tabindex="-1">Ist UI eXtension ein direkter Ersatz für Card-mod? <a class="header-anchor" href="#ist-ui-extension-ein-direkter-ersatz-fur-card-mod" aria-label="Permalink to &quot;Ist UI eXtension ein direkter Ersatz für Card-mod?&quot;">​</a></h2><p>Ja. Laut englischem Original ist UIX ein direkter Ersatz für Card-mod bis <strong>4.2.1</strong> und unterstützt dessen Karten- und Theme-Konfigurationen. Die Umstellung auf <code>uix:</code> und <code>uix-&lt;thing&gt;(-yaml)</code> ist empfohlen, aber nicht erforderlich. Bei gleichzeitig vorhandenen Konfigurationsschlüsseln hat <code>uix:</code> Vorrang. Das bedeutet Kompatibilität der Konfiguration, nicht paralleles Laden beider Ressourcen.</p><h2 id="ist-ui-extension-nur-card-mod-mit-anderer-dokumentation" tabindex="-1">Ist UI eXtension nur Card-mod mit anderer Dokumentation? <a class="header-anchor" href="#ist-ui-extension-nur-card-mod-mit-anderer-dokumentation" aria-label="Permalink to &quot;Ist UI eXtension nur Card-mod mit anderer Dokumentation?&quot;">​</a></h2><p>Nein. UIX nutzt eine eigene Architektur und eigene Frontend-Patches. Es adressiert neuere Home-Assistant-Strukturen, Dialoge, Theme-Variablen, DOM-Hilfen und erweiterte Funktionen, die über reines CSS-Injection-Styling hinausgehen.</p><h2 id="gibt-es-eine-liste-der-unterschiede-zwischen-card-mod-und-ui-extension" tabindex="-1">Gibt es eine Liste der Unterschiede zwischen Card-mod und UI eXtension? <a class="header-anchor" href="#gibt-es-eine-liste-der-unterschiede-zwischen-card-mod-und-ui-extension" aria-label="Permalink to &quot;Gibt es eine Liste der Unterschiede zwischen Card-mod und UI eXtension?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Funktion</th><th style="text-align:center;">Card-mod</th><th style="text-align:center;">UIX</th></tr></thead><tbody><tr><td>Korrektes Laden von <code>...-yaml</code> Theme-Variablen</td><td style="text-align:center;">Nein seit HA 2026.8.0</td><td style="text-align:center;">Ja</td></tr><tr><td>Korrekte Behandlung von <code>...-more-info(-yaml)</code></td><td style="text-align:center;">Nein seit HA 2026.3.0</td><td style="text-align:center;">Ja</td></tr><tr><td>Adaptive Dialogs für <code>...-dialog(-yaml)</code> patchen</td><td style="text-align:center;">Nein seit HA 2026.3.0</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./concepts/dom#dom-inspektionshelfer">DOM-Inspektionshelfer</a></td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./concepts/dom#host-element-pfad-auswahl">Host/Element-Pfad-Auswahl</a></td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./concepts/dom#express-search-selector">Express Search Selector</a></td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./forge/">Forge</a> als Custom-Lovelace-Element</td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./forge/foundries">Foundries</a> als wiederverwendbare Forges</td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./using/templates#makros">Makros</a> für wiederverwendbare Jinja-Templates</td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./forge/sparks/">Sparks</a> als gekapselte Erweiterungen für Forge-Elemente</td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./broker/">Broker</a> für deklarative Frontend-Interaktionen</td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./extras/frontend-states-throttling">Frontend State Throttling</a> optional</td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./extras/dialog-styling-delay">Dialog Styling Delay</a> optional</td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./using/view-backgrounds">Dashboard View Backgrounds</a></td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./using/section-backgrounds">Section Backgrounds</a></td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./using/icons#override-fur-eine-entitat">Icon Styling mit Entity Override</a></td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./using/images">Entitätsbilder stylen</a></td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./using/custom-panels">Custom Panels stylen</a>, auch in iFrames</td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td><a href="./using/apps">App- und Ingress-Panels stylen</a>, auch in iFrames</td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td>Reload-/Clear-Cache-Popup</td><td style="text-align:center;">Nein</td><td style="text-align:center;">Ja</td></tr><tr><td>Umfangreiche Doku mit visuellen Beispielen</td><td style="text-align:center;">Begrenzt</td><td style="text-align:center;">Ja</td></tr><tr><td>Mod-Card</td><td style="text-align:center;">Ja</td><td style="text-align:center;">Ja</td></tr><tr><td>CSS-Styling in Themes</td><td style="text-align:center;">Ja</td><td style="text-align:center;">Ja</td></tr><tr><td>Reload-/Clear-Cache-Service oder Action</td><td style="text-align:center;">Ja</td><td style="text-align:center;">Ja</td></tr><tr><td>Variablen wie aktueller Benutzer</td><td style="text-align:center;">Ja</td><td style="text-align:center;">Ja</td></tr><tr><td>CSS-Styling</td><td style="text-align:center;">Ja</td><td style="text-align:center;">Ja</td></tr><tr><td>Ressourcen-URL</td><td style="text-align:center;">Ja</td><td style="text-align:center;">Nicht nötig</td></tr></tbody></table><h2 id="hat-ui-extension-ressourcen-url-probleme" tabindex="-1">Hat UI eXtension Ressourcen-URL-Probleme? <a class="header-anchor" href="#hat-ui-extension-ressourcen-url-probleme" aria-label="Permalink to &quot;Hat UI eXtension Ressourcen-URL-Probleme?&quot;">​</a></h2><p>UIX wird als Integration bereitgestellt und muss normalerweise nicht als manuelle Lovelace-Ressource gepflegt werden. Dadurch werden viele Fehler vermieden, die bei falscher Ressourcen-URL, Browsercache oder HACS-Pfad entstehen können.</p><p>UIX registriert <code>uix.js</code> als zusätzliches Frontend-Modul und für CAST auch als Dashboard-Ressource. Beim Laden der Integration werden die Ressourcen automatisch mit ihrer Version versehen.</p><h2 id="muss-nach-einem-upgrade-manuell-der-cache-geleert-werden" tabindex="-1">Muss nach einem Upgrade manuell der Cache geleert werden? <a class="header-anchor" href="#muss-nach-einem-upgrade-manuell-der-cache-geleert-werden" aria-label="Permalink to &quot;Muss nach einem Upgrade manuell der Cache geleert werden?&quot;">​</a></h2><p>UIX zeigt eine Meldung mit der Schaltfläche <code>Reload Now</code>, wenn ein Neuladen zum Aktualisieren des Caches nötig ist. Nach 60 Sekunden wird die Seite automatisch neu geladen, damit auch unbeaufsichtigte Kiosks ihr Frontend aktualisieren.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Wenn eine Änderung nach einem Update nicht sichtbar wird, hilft ein harter Browser-Reload oder das Leeren des Companion-App-Caches trotzdem als erster Test.</p></div><h2 id="kann-die-reload-meldung-unterdruckt-werden" tabindex="-1">Kann die Reload-Meldung unterdrückt werden? <a class="header-anchor" href="#kann-die-reload-meldung-unterdruckt-werden" aria-label="Permalink to &quot;Kann die Reload-Meldung unterdrückt werden?&quot;">​</a></h2><p>Nein. Die Meldung stellt sicher, dass der UIX-JavaScript-Code im Frontend zur Version der UIX-Integration passt. Sie erscheint, wenn UIX geändert und Home Assistant neu gestartet wurde, der Browser aber noch ein zwischengespeichertes UIX-Bundle einer anderen Version verwendet.</p><p>Nach 60 Sekunden wird die Seite automatisch neu geladen.</p><div class="info custom-block"><p class="custom-block-title">Vorschau: UIX 9.0.0-beta.0</p><p>Der aktuelle <code>dev</code>-Stand liefert bis zum nächsten Home-Assistant-Neustart weiterhin die beim Start geladene UIX-Version aus. Nach einem Update kannst du Home Assistant neu starten, sobald du die neue Version aktivieren möchtest. Die frühere Aufforderung an Administratoren, wegen eines vorzeitigen Frontend-Updates sofort neu zu starten, entfällt. Dieses Verhalten ist nicht Bestandteil der stabilen Basis 8.4.0.</p></div><h2 id="wie-deinstalliere-ich-ui-extension" tabindex="-1">Wie deinstalliere ich UI eXtension? <a class="header-anchor" href="#wie-deinstalliere-ich-ui-extension" aria-label="Permalink to &quot;Wie deinstalliere ich UI eXtension?&quot;">​</a></h2><p>Entferne UIX über HACS oder aus <code>custom_components/uix</code>, starte Home Assistant neu und entferne anschließend UIX-spezifische Theme-Variablen oder <code>uix:</code>-Blöcke aus Dashboards, wenn sie nicht mehr benötigt werden.</p>',23)])])}const m=t(i,[["render",d]]);export{g as __pageData,m as default};
